                return "Pentium II Xeon";
            return "Pentium II";
        }
        if (Model == 6)
            return "Celeron";
        if (Model == 7) {
            if (L2CacheKB >= 1024)
                return "Pentium III Xeon";
            return "Pentium III";
        }
        if (Model == 8) {
            switch (BrandIndex) {
            case 1:
                return "Celeron";
            case 2:
                return "Pentium III";
            case 3:
                return "Pentium III Xeon";
            }
            break;
        }
        if (Model == 10)
            return "Pentium III Xeon";
        if (Model == 11)
            return "Pentium III";
        break;
    case 15:
        if (Stepping == 2)
            return "Pentium 4 (sample)";
        return "Pentium 4";
    }
    return "<unknown>";
}

